-- 3. VEHICLE INVENTORY (56 VERIFIED CARS & BIKES)
INSERT INTO public.vehicles (
  id, slug, name, brand, model, variant, year, type, category, body_type, bike_segment,
  registration_number, transmission, fuel_type, seating_capacity, engine_capacity, mileage,
  price_per_day, weekend_price, security_deposit, rating, review_count, cover_image,
  location_id, location_name, description, features, status, is_active
) VALUES
('veh-bk-01', 'hero-splendor-plus', 'Hero Splendor Plus XTEC', 'Hero', 'Splendor Plus', 'XTEC i3S Matt Grey', 2024, 'bike', 'Family & Commuter', NULL, 'Commuter', 'TN 09 BX 4102', 'Manual', 'Petrol', NULL, '97.2 cc', '68 km/l', 499, 599, 1000, 4.8, 142, '/images/vehicles/bikes/hero-splendor-plus.svg', 'hub-chn-tnagar', 'T. Nagar Hub, Chennai', 'India''s highest selling and most trusted family commuter. Unbeatable mileage, comfortable upright seat, and ultra-smooth i3S engine for low-cost city riding in Tamil Nadu.', ARRAY['i3S Idle Stop-Start', 'Digital Cluster with Bluetooth', 'USB Mobile Charger', 'Tubeless Tyres', 'ISI Helmet Included'], 'available', true),
('veh-bk-02', 'hero-hf-deluxe', 'Hero HF Deluxe Self-Start', 'Hero', 'HF Deluxe', 'Canvas Black Self Start', 2024, 'bike', 'Family & Commuter', NULL, 'Commuter', 'TN 02 AW 7891', 'Manual', 'Petrol', NULL, '97.2 cc', '70 km/l', 450, 550, 1000, 4.7, 98, '/images/vehicles/bikes/hero-hf-deluxe.svg', 'hub-chn-annanagar', 'Anna Nagar Hub, Chennai', 'Rugged, lightweight, and highly fuel-efficient workhorse. Perfect for students, office commutes, and daily errands across Chennai city traffic.', ARRAY['Self-Start', 'xSens Fuel Injection', 'Integrated Braking System', 'All-Black Theme', 'Full Fuel Tank Option'], 'available', true),
('veh-bk-03', 'honda-shine-125', 'Honda Shine 125 Drum OBD2', 'Honda', 'Shine 125', 'Disc Gen Black', 2024, 'bike', 'Family & Commuter', NULL, 'Commuter', 'TN 38 CR 1190', 'Manual', 'Petrol', NULL, '123.9 cc', '60 km/l', 599, 699, 1000, 4.9, 165, '/images/vehicles/bikes/honda-shine-125.svg', 'hub-cbe-gandhipuram', 'Gandhipuram Hub, Coimbatore', 'The executive family commuter benchmark. Honda eSP refined engine with 5-speed gearbox for refined, silent starting and zero vibrations on city bypasses.', ARRAY['eSP Engine with Silent ACG Starter', '5-Speed Gearbox', 'Combi Brake System (CBS)', 'DC Headlamp', 'Dual Helmet Option'], 'available', true),
('veh-bk-04', 'honda-sp125', 'Honda SP125 Sports Edition', 'Honda', 'SP125', 'Disc Sports Edition Imperial Red', 2024, 'bike', 'Family & Commuter', NULL, 'Commuter', 'TN 58 AA 9021', 'Manual', 'Petrol', NULL, '123.9 cc', '62 km/l', 649, 749, 1200, 4.8, 110, '/images/vehicles/bikes/honda-sp125.svg', 'hub-mdu-mattuthavani', 'Mattuthavani Integrated Bus Hub, Madurai', 'Modern styling meets premium commuter refinement. Fully digital console with real-time mileage indicator, LED headlamp, and sharp tank shrouds.', ARRAY['Full Digital Meter with Gear Indicator', 'LED Headlamp', 'Chrome Muffler Cover', 'CBS Braking', 'Low Fuel Warning'], 'available', true),
('veh-bk-05', 'honda-unicorn', 'Honda Unicorn 160 BS6', 'Honda', 'Unicorn', 'Pearl Siren Blue Single Disc', 2024, 'bike', 'Family & Commuter', NULL, 'Commuter', 'TN 45 BK 6632', 'Manual', 'Petrol', NULL, '162.7 cc', '52 km/l', 699, 799, 1500, 4.9, 180, '/images/vehicles/bikes/honda-unicorn.svg', 'hub-try-central', 'Central Trichy Hub, Tiruchirappalli (Trichy)', 'The king of comfort for over two decades. Plush single-piece seat, monoshock rear suspension, and bulletproof low-end torque for smooth family rides.', ARRAY['Single-Channel ABS', 'Rear Monoshock Suspension', 'Long Plush Seat', 'Engine Stop Switch', 'High Ground Clearance'], 'available', true),
('veh-bk-06', 'bajaj-platina-110', 'Bajaj Platina 110 ABS', 'Bajaj', 'Platina 110', 'Single Channel ABS Cocktail Wine Red', 2024, 'bike', 'Family & Commuter', NULL, 'Commuter', 'TN 27 DF 4310', 'Manual', 'Petrol', NULL, '115.4 cc', '72 km/l', 480, 580, 1000, 4.8, 88, '/images/vehicles/bikes/bajaj-platina-110.svg', 'hub-slm-newbusstand', 'Salem New Bus Stand Hub, Salem', 'The only commuter motorcycle in its segment equipped with anti-lock braking (ABS). Features Nitrox spring-on-spring suspension for superior pillion comfort.', ARRAY['Single-Channel ABS', 'Nitrox Spring-on-Spring Shocks', 'Quilt Comfort Seat', 'LED DRL', 'Wide Rubber Footpads'], 'available', true),
('veh-bk-07', 'tvs-raider-125', 'TVS Raider 125 SmartXonnect', 'TVS', 'Raider 125', 'TFT Edition Fiery Yellow', 2024, 'bike', 'Family & Commuter', NULL, 'Commuter', 'TN 22 ET 9923', 'Manual', 'Petrol', NULL, '124.8 cc', '64 km/l', 699, 799, 1200, 4.9, 134, '/images/vehicles/bikes/tvs-raider-125.svg', 'hub-chn-velachery', 'Velachery Hub, Chennai', 'Youthful and high-tech commuter from Tamil Nadu’s own TVS Motor Company. Features 5-inch color TFT console with turn-by-turn navigation and riding modes.', ARRAY['Color TFT Bluetooth Display', 'Eco & Power Riding Modes', 'Under-Seat Storage Space', 'Distinct Animalistic LED Headlamp', 'USB Fast Charger'], 'available', true),
('veh-bk-08', 'bajaj-pulsar-125', 'Bajaj Pulsar 125 Carbon', 'Bajaj', 'Pulsar 125', 'Split Seat Carbon Edition Solar Red', 2024, 'bike', 'Family & Commuter', NULL, 'Commuter', 'TN 11 AC 3321', 'Manual', 'Petrol', NULL, '124.4 cc', '55 km/l', 620, 720, 1200, 4.7, 92, '/images/vehicles/bikes/bajaj-pulsar-125.svg', 'hub-chn-tambaram', 'Tambaram Hub, Chennai', 'Pulsar DNA in an economical commuter package. Muscular fuel tank, twin pilot lamps, and signature split-seat styling with dependable mileage.', ARRAY['Muscular Fuel Tank with 3D Logo', 'Split Seats & Grab Rails', 'Clip-on Handlebars', 'Twin LED Taillamps', 'Anti-Skid Braking'], 'available', true),
('veh-bk-09', 'bajaj-pulsar-n160', 'Bajaj Pulsar N160 Dual ABS', 'Bajaj', 'Pulsar N160', 'Dual-Channel ABS Brooklyn Black', 2024, 'bike', 'City & Street', NULL, 'Street', 'TN 07 DB 8120', 'Manual', 'Petrol', NULL, '164.8 cc', '46 km/l', 850, 999, 1500, 4.8, 88, '/images/vehicles/bikes/bajaj-pulsar-n160.svg', 'hub-chn-adyar', 'Adyar Hub, Chennai', 'Aggressive street naked with class-first dual-channel ABS and projector bi-functional LED headlight. Precision handling and punchy mid-range pull.', ARRAY['Dual-Channel ABS', 'Bi-Functional LED Projector Headlamp', 'Underbelly Exhaust with Bass Exhaust Note', 'Infinity Display', 'USB Type-C Charger'], 'available', true),
('veh-bk-10', 'tvs-apache-rtr-160-4v', 'TVS Apache RTR 160 4V Special Edition', 'TVS', 'Apache RTR 160 4V', 'Special Edition Matte Pearl White', 2024, 'bike', 'City & Street', NULL, 'Street', 'TN 43 B 2291', 'Manual', 'Petrol', NULL, '159.7 cc', '45 km/l', 899, 1049, 1500, 4.9, 115, '/images/vehicles/bikes/tvs-apache-rtr-160-4v.svg', 'hub-ooty-charringcross', 'Charring Cross Nilgiris Hub, Ooty (Nilgiris)', 'Race-tuned 4-valve engine with 3 ride modes (Urban, Rain, Sport) and adjustable clutch/brake levers. Ideal for Ghat roads and city traffic alike.', ARRAY['3 Ride Modes (Rain/Urban/Sport)', 'Glide Through Traffic (GTT) Tech', 'SmartXonnect Bluetooth Telemetry', 'Bullpup Dual-Barrel Exhaust', 'Radial Rear Tyre'], 'available', true),
('veh-bk-11', 'tvs-apache-rtr-200-4v', 'TVS Apache RTR 200 4V Dual ABS', 'TVS', 'Apache RTR 200 4V', 'Dual-Channel ABS Gloss Black', 2024, 'bike', 'City & Street', NULL, 'Street', 'TN 37 CY 5541', 'Manual', 'Petrol', NULL, '197.7 cc', '38 km/l', 999, 1199, 2000, 4.9, 124, '/images/vehicles/bikes/tvs-apache-rtr-200-4v.svg', 'hub-cbe-rspuram', 'RS Puram Hub, Coimbatore', 'Equipped with Showa adjustable front suspension and RT-Slipper Clutch. Track-inspired corner carver for performance enthusiasts.', ARRAY['Showa Preload Adjustable Suspension', 'RT Slipper Clutch', 'Dual-Channel ABS with RLP', 'Race Telemetry with Lean Angle Indicator', '3 Riding Modes'], 'available', true),
('veh-bk-12', 'yamaha-fz-s-fi', 'Yamaha FZ-S FI V4 Deluxe', 'Yamaha', 'FZ-S FI', 'V4 Deluxe Metallic Grey', 2024, 'bike', 'City & Street', NULL, 'Street', 'TN 01 DJ 9910', 'Manual', 'Petrol', NULL, '149 cc', '48 km/l', 799, 949, 1500, 4.8, 96, '/images/vehicles/bikes/yamaha-fz-s-fi.svg', 'hub-chn-guindy', 'Guindy Hub, Chennai', 'Traction Control System (TCS) equipped street naked. Muscular street presence, wide 140mm radial rear tyre, and comfortable single-piece seat.', ARRAY['Traction Control System (TCS)', 'Single-Channel ABS with Disc Brakes', 'Class D Headlight with LED Flashers', 'Y-Connect App Integration', '140mm Radial Tyre'], 'available', true),
('veh-bk-13', 'yamaha-mt-15-v2', 'Yamaha MT-15 V2 Monster Energy', 'Yamaha', 'MT-15 V2', 'MotoGP Monster Energy Edition', 2024, 'bike', 'City & Street', NULL, 'Street', 'TN 14 AQ 3302', 'Manual', 'Petrol', NULL, '155 cc', '47 km/l', 1199, 1399, 2000, 5, 150, '/images/vehicles/bikes/yamaha-mt-15-v2.svg', 'hub-chn-omr-sholinganallur', 'OMR Sholinganallur Hub, Chennai', 'The Dark Warrior. Features R15-derived 155cc liquid-cooled 4-valve VVA engine, golden upside-down (USD) front forks, and aluminium swingarm.', ARRAY['Variable Valve Actuation (VVA)', 'Inverted Golden USD Front Forks', 'Traction Control & Dual ABS', 'Assist & Slipper Clutch', 'Aluminium Swingarm'], 'available', true),
('veh-bk-14', 'suzuki-gixxer-155', 'Suzuki Gixxer 155 Ride Connect', 'Suzuki', 'Gixxer 155', 'Bluetooth Ride Connect Metallic Sonic Silver', 2024, 'bike', 'City & Street', NULL, 'Street', 'TN 20 BK 1144', 'Manual', 'Petrol', NULL, '155 cc', '45 km/l', 799, 949, 1500, 4.8, 78, '/images/vehicles/bikes/suzuki-gixxer-155.svg', 'hub-chn-porur', 'Porur Hub, Chennai', 'European streetfighter stance with twin-muffler exhaust and SEP (Suzuki Eco Performance) engine for crisp throttle response and sharp city handling.', ARRAY['Suzuki Ride Connect Navigation', 'Twin-Outlet Exhaust with Chrome Cap', 'LED Headlamp & Taillamp', 'Rear Radial Tyre', 'Single-Channel ABS'], 'available', true),
('veh-bk-15', 'tvs-ronin', 'TVS Ronin Special Edition TD', 'TVS', 'Ronin', 'Triple Tone Dual ABS Nimbus Grey', 2024, 'bike', 'City & Street', NULL, 'Street', 'TN 72 AQ 7710', 'Manual', 'Petrol', NULL, '225.9 cc', '42 km/l', 1050, 1250, 2000, 4.8, 92, '/images/vehicles/bikes/tvs-ronin.svg', 'hub-tnv-vannarpettai', 'Vannarpettai Hub, Tirunelveli', 'Neo-retro scrambler crafted for spontaneous city rides and relaxed weekend touring. Golden USD forks, block pattern dual-purpose tyres, and voice assist.', ARRAY['Dual-Channel ABS with Rain/Urban Modes', 'Golden Showa USD Forks', 'Chain Cover & Custom Visor', 'Bluetooth Navigation with Voice Assist', 'Assist & Slipper Clutch'], 'available', true),
('veh-bk-16', 'ktm-duke-200', 'KTM Duke 200 Gen 3', 'KTM', 'Duke 200', 'Gen 3 Electronic Orange', 2024, 'bike', 'City & Street', NULL, 'Street', 'TN 23 BJ 9002', 'Manual', 'Petrol', NULL, '199.5 cc', '33 km/l', 1399, 1599, 2500, 4.9, 140, '/images/vehicles/bikes/ktm-duke-200.svg', 'hub-vlr-katpadi', 'Katpadi Railway Station Hub, Vellore', 'Pure, raw street thrill. 25 PS liquid-cooled DOHC motor, WP APEX upside-down forks, lightweight trellis chassis, and supermoto ABS mode.', ARRAY['Supermoto ABS Mode', 'WP APEX Big Piston 43mm USD Forks', 'LED Headlamp with DRL', 'Lightweight Trellis Frame', 'High-Spec Radials'], 'available', true),
('veh-bk-17', 'royal-enfield-hunter-350', 'Royal Enfield Hunter 350 Rebel', 'Royal Enfield', 'Hunter 350', 'Rebel Dapper Blue', 2024, 'bike', 'Touring & Highway', NULL, 'Touring', 'TN 10 CC 4419', 'Manual', 'Petrol', NULL, '349 cc', '36 km/l', 1100, 1300, 1500, 4.9, 172, '/images/vehicles/bikes/royal-enfield-hunter-350.jpg', 'hub-chn-tnagar', 'T. Nagar Hub, Chennai', 'Compact, punchy, and nimble urban-highway scrambler. The J-series 350cc engine offers signature thump with modern refinement and dual-channel ABS.', ARRAY['Dual-Channel ABS', 'Tripper Turn-by-Turn Navigation', 'Alloy Wheels with Tubeless Tyres', 'USB Quick Charging', 'DOT Helmet Included'], 'available', true),
('veh-bk-18', 'royal-enfield-classic-350', 'Royal Enfield Classic 350 Reborn', 'Royal Enfield', 'Classic 350', 'Dark Stealth Black Alloy', 2024, 'bike', 'Touring & Highway', NULL, 'Touring', 'TN 02 CX 1901', 'Manual', 'Petrol', NULL, '349 cc', '35 km/l', 1250, 1450, 2000, 5, 220, '/images/vehicles/bikes/royal-enfield-classic-350.svg', 'hub-chn-annanagar', 'Anna Nagar Hub, Chennai', 'The timeless legend reborn on the twin downtube spine chassis. Smooth, low-revving 349cc J-series engine built for long cruises down ECR or to Kodaikanal.', ARRAY['Dual-Channel ABS', 'Alloy Wheels with Tubeless Tyres', 'Rotary Switch Cubes', 'Wide Pillion Touring Seat', 'Signature Metallic Thump'], 'available', true),
